            return ResponseEntity.status(response.getCode()).body(response);
        }
        if (!canAccess(workspace, userId, role)) {
            ApiResponse<Map<String, Object>> response = ApiResponse.error(403, "权限不足");
            return ResponseEntity.status(response.getCode()).body(response);
        }
        return null;
    }

    private boolean canAccess(Workspace workspace, Long userId, String role) {
        return ADMIN_ROLE.equals(role) || workspace.getUserId().equals(userId);
    }
}
